from collections import Counter
class Solution:
    def isItPossible(self, word1: str, word2: str) -> bool:
        c1, c2 = Counter(word1), Counter(word2)
        d1, d2 = len(c1), len(c2)
        for a in c1:
            for b in c2:
                if a == b:
                    continue
                nd1 = d1 - (c1[a] == 1) + (c1[b] == 0)
                nd2 = d2 - (c2[b] == 1) + (c2[a] == 0)
                if nd1 == nd2:
                    return True
        return False

