class Solution {
public:
    bool isItPossible(string word1, string word2) {
        int c1[26] = {0}, c2[26] = {0};
        for (char ch : word1) c1[ch - 'a']++;
        for (char ch : word2) c2[ch - 'a']++;
        int d1 = 0, d2 = 0;
        for (int i = 0; i < 26; i++) d1 += c1[i] > 0;
        for (int i = 0; i < 26; i++) d2 += c2[i] > 0;
        for (int a = 0; a < 26; a++) if (c1[a])
            for (int b = 0; b < 26; b++) if (c2[b] && a != b) {
                int nd1 = d1 - (c1[a] == 1) + (c1[b] == 0);
                int nd2 = d2 - (c2[b] == 1) + (c2[a] == 0);
                if (nd1 == nd2) return true;
            }
        return false;
    }
};

