class Solution {
    public boolean isItPossible(String word1, String word2) {
        int[] c1 = new int[26], c2 = new int[26];
        for (char ch : word1.toCharArray()) c1[ch - 'a']++;
        for (char ch : word2.toCharArray()) c2[ch - 'a']++;
        int d1 = 0, d2 = 0;
        for (int i = 0; i < 26; i++) { if (c1[i] > 0) d1++; if (c2[i] > 0) d2++; }
        for (int a = 0; a < 26; a++) if (c1[a] > 0)
            for (int b = 0; b < 26; b++) if (c2[b] > 0 && a != b) {
                int nd1 = d1 - (c1[a] == 1 ? 1 : 0) + (c1[b] == 0 ? 1 : 0);
                int nd2 = d2 - (c2[b] == 1 ? 1 : 0) + (c2[a] == 0 ? 1 : 0);
                if (nd1 == nd2) return true;
            }
        return false;
    }
}

