var isItPossible = function(word1, word2) {
    const cnt = w => { const m = new Array(26).fill(0); for (const ch of w) m[ch.charCodeAt(0) - 97]++; return m; };
    const c1 = cnt(word1), c2 = cnt(word2);
    let d1 = c1.filter(x => x > 0).length, d2 = c2.filter(x => x > 0).length;
    for (let a = 0; a < 26; a++) if (c1[a] > 0)
        for (let b = 0; b < 26; b++) if (c2[b] > 0 && a !== b) {
            const nd1 = d1 - (c1[a] === 1) + (c1[b] === 0);
            const nd2 = d2 - (c2[b] === 1) + (c2[a] === 0);
            if (nd1 === nd2) return true;
        }
    return false;
};
